  "decision": "accept",
  "icd10_code": "I50.22",
  "code_display": "Chronic systolic heart failure",
  "guideline_citations": [
    {
      "url": "https://www.cms.gov/files/document/fy-2026-icd-10-cm-coding-guidelines.pdf",
      "quote": "If heart failure is present, assign an additional code from category I50 to identify the type of heart failure.",
      "source": "cms.gov"
    }
  ],
  "rationale": "The chart documents 'Heart failure with reduced ejection fraction – EF 35% on last echo,' which directly indicates systolic heart failure. Elevated BNP (580) and symptoms of dyspnea on exertion with 2-pillow orthopnea support an active, chronic condition. No negation, family history, screening, hypothetical, or resolved language is present. The specificity upgrade from a general heart failure code to I50.22 is supported by the documented reduced ejection fraction and clinical context.",
  "physician_query_needed": false
}
